commands:
mkdir -p src/climate/application && for name in ClimateApplication ClimateCompositeInput ClimateIoAdapters ClimateSemanticOutput; do git mv src/climate/${name}.h src/climate/application/${name}.h; git mv src/climate/${name}.cpp src/climate/application/${name}.cpp; done && python3 - <<'PY'
from pathlib import Path
import subprocess
repls = {
    'climate/ClimateApplication': 'climate/application/ClimateApplication',
    'climate/ClimateCompositeInput': 'climate/application/ClimateCompositeInput',
    'climate/ClimateIoAdapters': 'climate/application/ClimateIoAdapters',
    'climate/ClimateSemanticOutput': 'climate/application/ClimateSemanticOutput',
}
active_roots = ('src/', 'test/', 'tests/', 'scripts/', 'tools/', '.github/')
for rel in subprocess.check_output(['git','ls-files'], text=True).splitlines():
    if not (rel == 'CMakeLists.txt' or rel.startswith(active_roots)):
        continue
    p = Path(rel)
    try:
        text = p.read_text()
    except (UnicodeDecodeError, FileNotFoundError, IsADirectoryError):
        continue
    updated = text
    for old, new in repls.items():
        updated = updated.replace(old, new)
    if updated != text:
        p.write_text(updated)
PY
git diff --check && ! git grep -nE 'src/climate/(ClimateApplication|ClimateCompositeInput|ClimateIoAdapters|ClimateSemanticOutput)|climate/(ClimateApplication|ClimateCompositeInput|ClimateIoAdapters|ClimateSemanticOutput)' -- src test tests scripts tools .github CMakeLists.txt && echo APP_MOVE_V2_PATHS_PASS
